import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, SessionCompactResult, SessionRateLimit } from 'claude-code'

import type { BandLimit, BandStats, BandTtl, BandUsage } from '../types'
import { MARKER, buildSegments, fillTemplate, fitRow, observeTtl, stamp, tierOf } from './format'

const ARM_MS = 5000
// Work a command starts that must wait until the command has answered.
const AFTER_COMMAND_MS = 200
const TICK_MS = 30_000
const MAX_FILES = 40

// A request made right after a compaction, a /clear or a model change misses
// the cache for reasons that say nothing about its lifetime.
let isUnsettled = false

const NO_USAGE: BandUsage = {
  tokens: null,
  window: null,
  percent: null,
  fiveHour: null,
  sevenDay: null,
}

const NO_STATS: BandStats = { outputTokens: 0, model: null, effort: null, lastResponseAt: null, isCacheCold: false }

const usage = atom({ plugin: 'session-band', key: 'usage' } as const, NO_USAGE)
const stats = atom({ plugin: 'session-band', key: 'stats' } as const, NO_STATS)
const files = atom({ plugin: 'session-band', key: 'files' } as const, [])
const tick = atom({ plugin: 'session-band', key: 'tick' } as const, 0)
const armedUntil = atom({ plugin: 'session-band', key: 'armedUntil' } as const, 0)
const ttl = atom({ plugin: 'session-band', key: 'ttl' } as const, null)

type Measured = {
  context: { tokens?: number; window: number; percent?: number }
  rateLimits: SessionRateLimit[]
}

const limitOf = (limits: SessionRateLimit[], kind: string): BandLimit | null => {
  const found = limits.find(one => one.kind === kind)

  if (found === undefined) {
    return null
  }

  const resetsAt = found.resetsAt === undefined ? Number.NaN : Date.parse(found.resetsAt)

  return { percentUsed: found.percentUsed, resetsAt: Number.isNaN(resetsAt) ? null : resetsAt }
}

const measured = (from: Measured): BandUsage => ({
  tokens: from.context.tokens ?? null,
  window: from.context.window,
  percent: from.context.percent ?? null,
  fiveHour: limitOf(from.rateLimits, 'five_hour'),
  sevenDay: limitOf(from.rateLimits, 'seven_day'),
})

type Settings = {
  warnPercent: number
  alertPercent: number
  ttlMinutes: number
  handoffDir: string
  templateDir: string
}

async function template($: EngineInterface, set: Settings, name: string): Promise<string> {
  if (set.templateDir !== '' && (await $.fs.exists(`${set.templateDir}/${name}`))) {
    return $.fs.read(`${set.templateDir}/${name}`)
  }

  return $.fs.read(`${$.plugin.root}/templates/${name}`)
}

async function refresh($: EngineInterface): Promise<void> {
  const now = await $.session.usage()

  await update($, usage, () => measured(now))
}

// Before the first request only the session knows its model; effort stays null
// until a request reports it. A guess would be worse than an empty segment.
async function showModel($: EngineInterface): Promise<void> {
  if ((await read($, stats)).model !== null) {
    return
  }

  try {
    const model = await $.session.model()

    if (typeof model === 'string' && model !== '') {
      await update($, stats, one => (one.model === null ? { ...one, model } : one))
    }
  } catch {
    // Leave the segment empty.
  }
}

type Handoff = { path: string; text: string }

async function prepareHandoff($: EngineInterface, set: Settings, note: string): Promise<Handoff> {
  const now = await $.clock.now()
  const path = `${set.handoffDir}/handoff-${stamp(now)}.md`
  const text = fillTemplate(await template($, set, 'handoff.md'), {
    path,
    files: await read($, files),
    note,
  })

  return { path, text }
}

// The call resolves only as the handoff turn starts, so nothing waits on it; a
// refusal or a drop is told in a toast instead of vanishing.
function submitHandoff($: EngineInterface, one: Handoff): void {
  $.prompt.submit({ text: one.text }).then(
    done => {
      if (done.drop !== undefined) {
        $.ui.toast(`Handoff not sent: ${done.drop}`)
      }
    },
    () => $.ui.toast('Handoff failed: the prompt could not be submitted.'),
  )
}

async function compact($: EngineInterface, set: Settings, note: string): Promise<void> {
  const instructions = fillTemplate(await template($, set, 'compact.md'), {
    files: await read($, files),
    note,
  })

  let done: SessionCompactResult

  try {
    // This plugin's own session.compact hook does not see its own call.
    done = await $.session.compact({ instructions })
  } catch (error) {
    // The engine says why; a turn running is one reason of several, and a
    // guess here would hide the others.
    $.ui.toast(`Compact failed: ${firstLine(error)}`)

    return
  }

  if (done.skip !== undefined) {
    $.ui.toast(`Compact skipped: ${done.skip}`)

    return
  }

  isUnsettled = true
  await compacted($)
}

function firstLine(error: unknown): string {
  const text = error instanceof Error ? error.message : String(error)

  return text.split('\n')[0]?.trim() || 'no reason given'
}

// The engine measures the context again only with the next response, and the
// compaction's own `tokensAfter` counts the conversation alone, without the
// system prompt and tools, so the row shows no context until that response
// rather than a stale or a wrong figure. The old prefix is gone, so the cache
// starts cold.
async function compacted($: EngineInterface): Promise<void> {
  await update($, usage, one => ({ ...one, tokens: null, percent: null }))
  await update($, stats, one => ({ ...one, isCacheCold: true }))
}

async function lifetime($: EngineInterface, set: Settings): Promise<BandTtl> {
  return (await read($, ttl)) ?? { minutes: set.ttlMinutes, source: 'config' }
}

async function remember($: EngineInterface, path: unknown): Promise<void> {
  if (typeof path !== 'string' || path === '') {
    return
  }

  await update($, files, list => [...list.filter(one => one !== path), path].slice(-MAX_FILES))
}

export const register: Register = (on, options) => {
  const set: Settings = {
    warnPercent: Number(options.warnPercent ?? 60),
    alertPercent: Number(options.alertPercent ?? 75),
    ttlMinutes: Number(options.cacheTtlMinutes ?? 60),
    handoffDir: String(options.handoffDir ?? '.handoff').replace(/\/+$/, '') || '.handoff',
    templateDir: String(options.templateDir ?? '').replace(/\/+$/, ''),
  }

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'handoff',
      description: 'Write a handoff file for a fresh session (optional note after the name)',
    })
    await $.command.register({
      name: 'compact-keep',
      description: 'Compact with instructions that keep decisions, constraints and state (optional note)',
    })
    await refresh($)
    await showModel($)
    $.clock.every(TICK_MS, () => {
      void update($, tick, count => count + 1)
    })

    return next(e)
  })

  on('session.measure', async ($, e, next) => {
    await update($, usage, () => measured(e))

    return next(e)
  })

  // A /clear moves the process to a new session id and fires no session.start.
  // The state is kept per session id, so the new session reads every atom at its
  // initial: out, cache and the edited files start from zero without a write
  // here, and a write from session.end would land in the old session. What the
  // new session does not have is the model and the usage readings, so ask again.
  // The timer registered in session.start belongs to the process and keeps going.
  // The event's own model is absent on a clear; the session knows it.
  on('classic.SessionStart', async ($, e, next) => {
    if (e.source === 'clear') {
      isUnsettled = true
      await refresh($)
      await showModel($)
    }

    return next(e)
  })

  // A compaction from /compact, the threshold or another plugin. A subagent
  // compacts its own transcript, a precompute only prepares one, and a skip
  // keeps it.
  on('session.compact', async ($, e, next) => {
    const done = await next(e)

    if (e.agentId === undefined && e.trigger !== 'precompute' && done.skip === undefined) {
      isUnsettled = true
      await compacted($)
    }

    return done
  })

  on('classic.PostModelSwitch', async ($, e, next) => {
    isUnsettled = true
    await update($, ttl, () => ({ minutes: e.cache_ttl === '5m' ? 5 : 60, source: 'engine' as const }))

    if (e.from_model !== e.to_model) {
      // The event carries no effort, and the new model may run at another one.
      await update($, stats, one => ({ ...one, model: e.to_model, effort: null, isCacheCold: true }))
    }

    return next(e)
  })

  on('turn.step', async function* ($, e, next) {
    if (e.agentId !== undefined) {
      return yield* next(e)
    }

    const startedAt = await $.clock.now()
    const before = await read($, stats)
    const priorTokens = (await read($, usage)).tokens ?? 0
    const effort = e.effort === undefined ? null : String(e.effort)

    await update($, stats, one => ({ ...one, model: e.model, effort }))

    const result = yield* next(e)

    if (result.usage === null) {
      return result
    }

    const assumed = await lifetime($, set)
    const corrected =
      e.index === 0 &&
      !isUnsettled &&
      !before.isCacheCold &&
      before.lastResponseAt !== null &&
      before.model === e.model
        ? observeTtl({
            minutes: assumed.minutes,
            idleMs: startedAt - before.lastResponseAt,
            priorTokens,
            cacheRead: result.usage.cache_read_input_tokens,
          })
        : null

    isUnsettled = false

    if (corrected !== null) {
      await update($, ttl, () => ({ minutes: corrected, source: 'observed' as const }))
      $.ui.toast(`Prompt cache lifetime looks like ${corrected} minutes here; the countdown now uses that.`)
    }

    const answeredAt = await $.clock.now()

    await update($, stats, one => ({ ...one, lastResponseAt: answeredAt, isCacheCold: false }))

    return result
  })

  on('turn.complete', async ($, e, next) => {
    if (e.agentId === undefined) {
      const now = await $.clock.now()
      const out = e.usage?.output_tokens ?? 0

      await update($, stats, one => ({
        ...one,
        outputTokens: one.outputTokens + out,
        model: e.usage?.model ?? one.model,
        lastResponseAt: e.usage === undefined ? one.lastResponseAt : now,
        isCacheCold: e.usage === undefined ? one.isCacheCold : false,
      }))
    }

    return next(e)
  })

  on('tool.call', { tool: 'Edit' }, async ($, e, next) => {
    const ran = await next(e)

    if (ran.deny === undefined && ran.isError !== true) {
      await remember($, e.file_path)
    }

    return ran
  })

  on('tool.call', { tool: 'Write' }, async ($, e, next) => {
    const ran = await next(e)

    if (ran.deny === undefined && ran.isError !== true) {
      await remember($, e.file_path)
    }

    return ran
  })

  on('command.run', { command: 'handoff' }, async ($, e) => {
    let one: Handoff

    try {
      one = await prepareHandoff($, set, e.args)
    } catch {
      return { text: 'Handoff failed: the template could not be read.' }
    }

    // A prompt submitted while this hook runs would wait on the turn the command
    // holds, and the host refuses it, so it goes once the command has answered.
    $.clock.after(AFTER_COMMAND_MS, () => submitHandoff($, one))

    return { text: `Handoff requested. Claude will write ${one.path}.` }
  })

  on('command.run', { command: 'compact-keep' }, async ($, e) => {
    // Compaction runs between turns, so it starts once this command has answered.
    $.clock.after(AFTER_COMMAND_MS, () => {
      compact($, set, e.args).catch(() => $.ui.toast('Compact failed: the template could not be read.'))
    })

    return { text: 'Compacting with the keep-instructions.' }
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey) {
      return next(e)
    }

    await read($, tick)

    const now = await $.clock.now()
    const seen = await read($, usage)
    const tier = tierOf(seen.percent, set)
    const isArmed = (await read($, armedUntil)) > now
    // The desktop app shows the model and effort beside its own prompt box.
    const row = fitRow(
      buildSegments(seen, await read($, stats), now, set, (await lifetime($, set)).minutes, e.surface === 'terminal'),
      e.props.bodyColumns,
    )
    const { Box, Button, Text } = $.ui.resolve(e)

    const pressHandoff = (): void => {
      void prepareHandoff($, set, '').then(
        one => {
          submitHandoff($, one)
          $.ui.toast(`Handoff requested: ${one.path}`)
        },
        () => $.ui.toast('Handoff failed: the template could not be read.'),
      )
    }

    const pressCompact = (): void => {
      void (async () => {
        const pressedAt = await $.clock.now()

        if ((await read($, armedUntil)) > pressedAt) {
          await update($, armedUntil, () => 0)
          await compact($, set, '')

          return
        }

        await update($, armedUntil, () => pressedAt + ARM_MS)
        $.clock.after(ARM_MS, () => {
          void update($, tick, count => count + 1)
        })
      })().catch(() => $.ui.toast('Compact failed: the template could not be read.'))
    }

    // The blank line above also holds the engine's collapse mark, `[-]`, drawn
    // at the band's top right; without it the mark covers the end of the row.
    return (
      <Box flexDirection="row" marginTop={1}>
        <Text dimColor>{MARKER}</Text>
        {row.segments.map((one, index) => (
          <Text color={one.color} dimColor={one.isDim} wrap="truncate">
            {index === 0 ? '' : ' | '}
            {one.text}
          </Text>
        ))}
        <Box flexGrow={1} />
        <Text> </Text>
        {row.isCompact ? (
          <Button key="handoff" label="h" plain dimColor={tier === 'quiet'} onPress={pressHandoff} />
        ) : (
          <Button
            key="handoff"
            label="handoff"
            hotkey="h"
            plain
            dimColor={tier === 'quiet'}
            onPress={pressHandoff}
          />
        )}
        <Text> </Text>
        {row.isCompact && !isArmed ? (
          <Button key="compact" label="c" plain dimColor={tier !== 'alert'} onPress={pressCompact} />
        ) : (
          <Button
            key="compact"
            label={isArmed ? 'again to compact' : 'compact'}
            hotkey="c"
            plain
            dimColor={tier !== 'alert' && !isArmed}
            onPress={pressCompact}
          />
        )}
      </Box>
    )
  })
}

