import type { BandLimit, BandStats, BandUsage } from '../types'

export type Tier = 'quiet' | 'warn' | 'alert'

export type Segment = {
  id: 'ctx' | 'cache' | 'fiveHour' | 'week' | 'spend' | 'model'
  text: string
  /** A theme color key, or undefined for the default text color. */
  color?: string
  isDim: boolean
  /** Lower stays longer when the row is too narrow. */
  priority: number
}

export type Thresholds = { warnPercent: number; alertPercent: number }

export type Row = { segments: Segment[]; isCompact: boolean }

const SEPARATOR = ' | '
/** Leads the row so it reads as a status row, not the last line of output. Never dropped. */
export const MARKER = '▎ '
const BUTTONS_WIDE = 'h: handoff c: compact'.length
const BUTTONS_COMPACT = 'h c'.length

export const tierOf = (percent: number | null, at: Thresholds): Tier => {
  if (percent === null) {
    return 'quiet'
  }

  if (percent >= at.alertPercent) {
    return 'alert'
  }

  return percent >= at.warnPercent ? 'warn' : 'quiet'
}

export const colorOf = (tier: Tier): string | undefined => {
  if (tier === 'alert') {
    return 'error'
  }

  return tier === 'warn' ? 'warning' : undefined
}

/** 950 -> "950", 108000 -> "108k", 1250000 -> "1.3M". */
export const formatTokens = (count: number): string => {
  if (count < 1000) {
    return String(Math.round(count))
  }

  if (count < 1_000_000) {
    return `${Math.round(count / 1000)}k`
  }

  return `${(count / 1_000_000).toFixed(1)}M`
}

/** 45_000 -> "<1m", 2_460_000 -> "41m", 7_800_000 -> "2h10m". */
export const formatSpan = (ms: number): string => {
  const minutes = Math.floor(ms / 60_000)

  if (minutes < 1) {
    return '<1m'
  }

  if (minutes < 60) {
    return `${minutes}m`
  }

  const hours = Math.floor(minutes / 60)
  const rest = minutes % 60

  if (hours >= 48) {
    return `${Math.floor(hours / 24)}d`
  }

  return rest === 0 ? `${hours}h` : `${hours}h${rest}m`
}

/** "claude-opus-5-5-20260915" -> "opus-5-5". */
export const shortModel = (model: string): string =>
  model.replace(/^claude-/, '').replace(/-\d{8}$/, '')

const limitText = (label: string, limit: BandLimit, now: number): string => {
  const used = `${label} ${Math.round(limit.percentUsed)}%`

  if (limit.resetsAt === null || limit.resetsAt <= now) {
    return used
  }

  return `${used} (resets ${formatSpan(limit.resetsAt - now)})`
}

/**
 * How long the prompt cache is assumed to stay warm: an estimate counted from
 * the last response, since the engine reports no remaining lifetime.
 */
export const cacheText = (
  lastResponseAt: number | null,
  now: number,
  ttlMinutes: number,
  isReset = false,
): { text: string; isCold: boolean } | null => {
  if (isReset) {
    return { text: 'cache cold', isCold: true }
  }

  if (lastResponseAt === null) {
    return null
  }

  const left = ttlMinutes * 60_000 - (now - lastResponseAt)

  return left <= 0
    ? { text: 'cache cold', isCold: true }
    : { text: `cache ~${formatSpan(left)}`, isCold: false }
}

export const buildSegments = (
  usage: BandUsage,
  stats: BandStats,
  now: number,
  at: Thresholds,
  ttlMinutes: number,
  hasModel: boolean,
): Segment[] => {
  const segments: Segment[] = []
  const tier = tierOf(usage.percent, at)

  if (usage.percent !== null && usage.window !== null) {
    const used = usage.tokens === null ? '' : ` (${formatTokens(usage.tokens)}/${formatTokens(usage.window)})`

    segments.push({
      id: 'ctx',
      text: `ctx ${Math.round(usage.percent)}%${used}`,
      color: colorOf(tier),
      isDim: false,
      priority: 0,
    })
  }

  const cache = cacheText(stats.lastResponseAt, now, ttlMinutes, stats.isCacheCold === true)

  if (cache !== null) {
    segments.push({
      id: 'cache',
      text: cache.text,
      color: cache.isCold ? 'warning' : undefined,
      isDim: false,
      priority: 2,
    })
  }

  if (usage.fiveHour !== null) {
    segments.push({
      id: 'fiveHour',
      text: limitText('5h', usage.fiveHour, now),
      color: usage.fiveHour.percentUsed >= 90 ? 'error' : undefined,
      isDim: false,
      priority: 1,
    })
  }

  if (usage.sevenDay !== null) {
    segments.push({
      id: 'week',
      text: `week ${Math.round(usage.sevenDay.percentUsed)}%`,
      color: usage.sevenDay.percentUsed >= 90 ? 'error' : undefined,
      isDim: usage.sevenDay.percentUsed < 50,
      priority: 3,
    })
  }

  // Generated tokens, not dollars: one figure that reads the same on a
  // subscription, an API key and a local model, with no price behind it.
  if (stats.outputTokens > 0) {
    segments.push({
      id: 'spend',
      text: `out ${formatTokens(stats.outputTokens)}`,
      isDim: true,
      priority: 4,
    })
  }

  if (hasModel && stats.model !== null) {
    const effort = stats.effort === null ? '' : ` ${stats.effort}`

    segments.push({
      id: 'model',
      text: `${shortModel(stats.model)}${effort}`,
      isDim: true,
      priority: 5,
    })
  }

  return segments
}

const widthOf = (segments: Segment[], buttons: number): number =>
  MARKER.length +
  segments.reduce((sum, one) => sum + one.text.length, 0) +
  Math.max(0, segments.length - 1) * SEPARATOR.length +
  2 +
  buttons

/**
 * Fits the row to `columns`: the record group goes first (model, then spend),
 * then the buttons shrink to one letter each, then the remaining segments go
 * by priority. The marker and `ctx` are never dropped.
 */
export const fitRow = (all: Segment[], columns: number): Row => {
  let segments = [...all]
  let isCompact = false

  const dropLast = (): boolean => {
    const worst = segments.reduce<Segment | null>(
      (found, one) => (one.priority > (found?.priority ?? 0) ? one : found),
      null,
    )

    if (worst === null) {
      return false
    }

    segments = segments.filter(one => one !== worst)

    return true
  }

  while (widthOf(segments, isCompact ? BUTTONS_COMPACT : BUTTONS_WIDE) > columns) {
    const worst = Math.max(0, ...segments.map(one => one.priority))

    if (worst >= 4) {
      dropLast()
    } else if (!isCompact) {
      isCompact = true
    } else if (!dropLast()) {
      break
    }
  }

  return { segments, isCompact }
}

/**
 * "20261003-155407", in UTC: a file name stamp, not a time shown to anyone.
 * To the second, so two handoffs in the same minute do not share a file.
 */
export const stamp = (now: number): string => {
  const iso = new Date(now).toISOString()

  return `${iso.slice(0, 4)}${iso.slice(5, 7)}${iso.slice(8, 10)}-${iso.slice(11, 13)}${iso.slice(14, 16)}${iso.slice(17, 19)}`
}

export type Fill = { path?: string; files: string[]; note: string }

/** Fills a template's `{{path}}`, `{{files}}` and `{{note}}`. */
export const fillTemplate = (template: string, fill: Fill): string => {
  const files = fill.files.length === 0 ? '- none recorded' : fill.files.map(one => `- ${one}`).join('\n')
  const note = fill.note.trim() === '' ? '' : `The user adds: ${fill.note.trim()}`

  return template
    .replaceAll('{{path}}', fill.path ?? '')
    .replaceAll('{{files}}', files)
    .replaceAll('{{note}}', note)
    .replace(/\n{3,}/g, '\n\n')
    .trim()
}

const SHORT_TTL = 5
const LONG_TTL = 60
const MIN_PRIOR_TOKENS = 8000
const MIN_IDLE_MS = 60_000

export type Observation = {
  /** The lifetime assumed so far, in minutes. */
  minutes: number
  /** How long the session sat idle before this request, in milliseconds. */
  idleMs: number
  /** Context tokens the previous response was answered over. */
  priorTokens: number
  /** Tokens this request read from the prompt cache. */
  cacheRead: number
}

/**
 * Corrects the assumed cache lifetime from what a request actually read.
 *
 * After an idle gap, the first request either reads most of the previous
 * context from the cache (it was still warm) or almost none of it (it had gone
 * cold). Cold inside the assumed lifetime means the lifetime is shorter than
 * assumed; warm past it means it is longer. The cache has two lifetimes, five
 * minutes and one hour, so those are the only corrections made.
 *
 * @returns the corrected lifetime in minutes, or null when nothing changes
 */
export const observeTtl = (seen: Observation): number | null => {
  if (seen.priorTokens < MIN_PRIOR_TOKENS || seen.idleMs < MIN_IDLE_MS) {
    return null
  }

  const idleMinutes = seen.idleMs / 60_000
  const share = seen.cacheRead / seen.priorTokens

  if (share < 0.1 && idleMinutes < seen.minutes && idleMinutes >= SHORT_TTL && seen.minutes > SHORT_TTL) {
    return SHORT_TTL
  }

  if (share >= 0.5 && idleMinutes > seen.minutes && seen.minutes < LONG_TTL) {
    return LONG_TTL
  }

  return null
}

