{
  "name": "session-band",
  "version": "0.1.0",
  "description": "A status row above the prompt (context, cache, usage limits, generated tokens) with a handoff-file action and guided compact.",
  "author": {
    "name": "Leon Qi",
    "url": "https://github.com/leonqi-io"
  },
  "license": "MIT",
  "types": "./types/index.d.ts",
  "userConfig": {
    "warnPercent": {
      "type": "number",
      "title": "Context warning (%)",
      "description": "Context fill at which the row turns to the warning color and handoff becomes the main action.",
      "default": 60,
      "min": 1,
      "max": 100
    },
    "alertPercent": {
      "type": "number",
      "title": "Context alert (%)",
      "description": "Context fill at which the row turns to the alert color.",
